-- 주간 콘텐츠 2026-10-19 (월): 번역 연습 5문장(KR→EN 3, EN→KR 2) + 주간 리포트 2 + 영어 카피 브리프 3 + 복습 단어 6 + 교차번역 3회차 6개
-- 교차번역은 지난 회차(10/05)에서 14일이 지나 3회차를 넣어요.
-- 이메일은 저장하지 않고 이름으로 찾아요(members.display_name).
begin;
insert into public.drills (id, dir, topic, sort, context, source, for_author, focus) values
  ('dr-20261019-ke-m1','KR→EN','marketing',1,'동네 꽃집 가을 엽서 문구','꽃은 시들어도 그날의 기분은 오래 남아요. 이번 주말까지 모든 꽃다발에 손글씨 카드를 무료로 넣어 드려요.',(select email from public.members where display_name='희주'),'원문 두 문장 끝까지 옮기기'),
  ('dr-20261019-ke-d1','KR→EN','daily',1,'친구에게 쇼핑 후기 문자','그 재킷 매장에서 입어 봤는데 생각보다 커서 그냥 나왔어. 한 치수 작은 걸로 다시 주문해 볼까 봐.',null,''),
  ('dr-20261019-ke-b1','KR→EN','business',1,'동료에게 회의 시간 변경 부탁','죄송한데 내일 회의를 오후로 미룰 수 있을까요? 오전에 급한 일정이 잡혀서요.',null,''),
  ('dr-20261019-ek-b1','EN→KR','business',1,'분기 실적 보고 슬라이드','Online orders now make up a third of our sales, up from a quarter last year.',(select email from public.members where display_name='혜림'),'분수 표현(a third, a quarter)'),
  ('dr-20261019-ek-t1','EN→KR','travel',1,'기차역 안내 방송','Please keep your belongings with you at all times. Unattended bags may be removed.',null,'');
insert into public.drill_models (drill_id, best, alternatives, notes) values
  ('dr-20261019-ke-m1','Flowers fade, but the feeling stays. Through this weekend, every bouquet comes with a free handwritten card.','["The flowers won''t last forever, but the moment will. Until Sunday, we''ll tuck a handwritten card into every bouquet, on us.", "Flowers wilt; the feeling lingers. This weekend only, every bouquet includes a complimentary handwritten note."]','[{"phrase": "시들어도 → fade / wilt", "why": "die를 쓰면 너무 무거워요. 카피에서는 fade가 ''기분''과 대비를 만들기 좋아요."}, {"phrase": "무료로 넣어 드려요 → comes with a free ~ / on us", "why": "We put a card for free처럼 직역하면 어색해요. 상품에 딸려 온다는 comes with가 광고 문장이에요."}, {"phrase": "둘째 문장(기한과 혜택)", "why": "첫 문장만 예쁘게 옮기고 끝내면 ''이번 주말까지 카드 무료''라는 정보가 사라져요. 두 문장을 끝까지 옮겨요."}]'),
  ('dr-20261019-ke-d1','I tried that jacket on at the store, but it was bigger than I expected, so I just left. I might order it again in a size down.','["I tried on the jacket in the store, and it ran bigger than I thought, so I walked out without it. Maybe I''ll reorder it a size smaller.", "Tried the jacket on in person and it was too big, so I didn''t get it. I''m thinking of ordering one size down."]','[{"phrase": "입어 보다 → try on", "why": "wear는 ''입고 있다''는 상태예요. 사기 전에 맞는지 입어 보는 건 try on이에요."}, {"phrase": "한 치수 작은 걸로 → in a size down / one size smaller", "why": "small size로 하면 S 사이즈로 읽혀요. 지금보다 한 단계 작은 건 a size down이에요."}, {"phrase": "그냥 나왔어 → I just left / walked out without it", "why": "I just came out은 어디서 나왔는지만 말해요. 안 사고 나왔다는 뜻을 살려요."}]'),
  ('dr-20261019-ke-b1','Sorry, could we push tomorrow''s meeting back to the afternoon? I''ve got something urgent in the morning.','["Sorry, would it be possible to move tomorrow''s meeting to the afternoon? An urgent commitment has come up in the morning.", "Apologies, could we shift tomorrow''s meeting to later in the day? Something urgent has landed on my morning."]','[{"phrase": "미루다 → push back / move", "why": "delay는 일이 지연됐다는 느낌이라 부탁할 때는 push back, move가 자연스러워요."}, {"phrase": "급한 일정이 잡혀서요 → I''ve got something urgent", "why": "An urgent schedule was made처럼 옮기면 어색해요. 이유는 짧고 부드럽게 말해요."}, {"phrase": "죄송한데 ~할 수 있을까요? → Sorry, could we ~?", "why": "동료에게는 I''m sorry but you must가 아니라 could we로 함께 정하는 말투가 좋아요."}]'),
  ('dr-20261019-ek-b1','현재 온라인 주문이 매출의 3분의 1을 차지합니다. 작년 4분의 1에서 늘었습니다.','["온라인 주문 비중이 작년 4분의 1에서 올해 3분의 1로 커졌습니다.", "이제 매출의 3분의 1이 온라인 주문에서 나옵니다. 작년에는 4분의 1이었습니다."]','[{"phrase": "a third → 3분의 1", "why": "third를 ''세 번째''로 읽으면 안 돼요. a third, a quarter는 분수예요. a fifth도 5분의 1이에요."}, {"phrase": "make up → 차지하다", "why": "''구성하다''로 옮기면 딱딱해요. 비율을 말할 때는 ''차지하다'', ''비중''을 써요."}, {"phrase": "up from ~ → ~에서 늘었다", "why": "''~로부터 위로''가 아니에요. 이전 수치에서 늘었다는 뜻이라 보고 자료에서는 문장을 나눠도 좋아요."}]'),
  ('dr-20261019-ek-t1','소지품은 항상 직접 챙겨 주시기 바랍니다. 주인 없이 놓인 가방은 수거될 수 있습니다.','["개인 소지품은 늘 몸에 지니고 계시기 바랍니다. 방치된 가방은 수거될 수 있습니다.", "소지품을 꼭 곁에 두세요. 주인이 없는 가방은 역무원이 수거할 수 있습니다."]','[{"phrase": "at all times → 항상", "why": "''모든 시간에''로 옮기면 번역투예요. 안내 방송에서는 ''항상'', ''늘''이면 돼요."}, {"phrase": "unattended → 주인 없이 놓인 / 방치된", "why": "''주의받지 않은''이 아니에요. 곁에 사람이 없는 물건을 말해요."}, {"phrase": "may be removed → 수거될 수 있습니다", "why": "''제거될 수 있습니다''는 너무 세요. 역이나 공항 안내에서는 ''수거''를 써요."}]');
with s as (
  insert into public.sessions (no, dir, level, title, source) values
    (3,'KR→EN','쉬움','일상 · 강아지 산책 부탁','이번 주말에 우리 강아지 산책 좀 부탁해도 될까? 사료는 현관 옆 서랍에 있어.'),
    (3,'EN→KR','쉬움','안내문 · 엘리베이터 운행 중지','The elevator will be out of service on Thursday from 9 a.m. to noon. Please use the stairs on the east side.'),
    (3,'KR→EN','보통','생활 기사 · 공유 부엌','한 아파트 단지가 빈 상가를 공유 부엌으로 바꿨다. 주민들은 시간 단위로 예약해 요리 수업을 열거나 이웃과 음식을 나눈다. 운영비는 이용자들이 나눠 낸다.'),
    (3,'EN→KR','보통','생활 기사 · 손편지','Handwritten letters are making a quiet comeback among people in their twenties. Some say writing by hand forces them to slow down and choose their words more carefully. Stationery shops report that letter sets are selling out on weekends.'),
    (3,'KR→EN','실전','대역 기사 · 사회 (예시 원문)','한 지방 도시가 버스 노선을 줄이는 대신 호출형 미니버스를 도입했다. 주민이 앱으로 부르면 가까운 정류장까지 와서 태워 가는 방식이다. 이용객은 늘었지만, 스마트폰이 익숙하지 않은 고령층은 오히려 불편해졌다는 목소리도 나온다.'),
    (3,'EN→KR','실전','대역 기사 · 일과 노동 (예시 원문)','A mid-sized design firm has moved to a four-day week without cutting pay, asking staff to drop low-value meetings instead. Six months in, the company says output has held steady and sick days have fallen by a third. Skeptics note that the results may not carry over to industries with fixed shifts.')
  returning id, title
)
insert into public.session_models (session_id, best, alternatives, notes)
select s.id, m.best, m.alternatives::jsonb, m.notes::jsonb
from s join (values
  ('일상 · 강아지 산책 부탁','Would you mind walking my dog this weekend? The food''s in the drawer by the front door.','["Could you take my dog for a walk this weekend? His food is in the drawer next to the front door.", "Any chance you could walk my dog this weekend? You''ll find the food in the drawer by the door."]','[{"phrase": "강아지 산책 부탁 → walk my dog", "why": "walk는 ''산책시키다''라는 타동사로도 써요. take my dog for a walk도 같은 뜻이에요."}, {"phrase": "부탁해도 될까? → Would you mind ~ing? / Any chance you could ~?", "why": "Can I ask you a favor to walk처럼 늘이지 않아요. 친구 사이 부탁 표현이 따로 있어요."}, {"phrase": "현관 옆 → by the front door", "why": "entrance는 건물 입구 느낌이에요. 집 현관은 front door예요."}]'),
  ('안내문 · 엘리베이터 운행 중지','목요일 오전 9시부터 낮 12시까지 엘리베이터 운행이 중지됩니다. 동쪽 계단을 이용해 주시기 바랍니다.','["목요일 오전 9시~정오에는 엘리베이터를 이용하실 수 없습니다. 동쪽 계단을 이용해 주세요.", "엘리베이터는 목요일 오전 9시부터 12시까지 운행하지 않습니다. 이 시간에는 동쪽 계단을 이용해 주십시오."]','[{"phrase": "out of service → 운행이 중지됩니다", "why": "''서비스 밖''이 아니에요. 엘리베이터·기계 안내에서는 ''운행 중지'', ''이용할 수 없습니다''예요."}, {"phrase": "noon → 낮 12시 / 정오", "why": "12 p.m.을 오전·오후로 헷갈리기 쉬워요. 안내문에서는 ''낮 12시''가 가장 분명해요."}, {"phrase": "Please use ~ → 이용해 주시기 바랍니다", "why": "''사용하세요''는 지시처럼 들려요. 안내문은 ''이용해 주시기 바랍니다''로 끝내요."}]'),
  ('생활 기사 · 공유 부엌','An apartment complex has turned a vacant storefront into a shared kitchen. Residents book it by the hour to run cooking classes or share meals with neighbors. Running costs are split among the people who use it.','["One apartment complex has converted an empty shop unit into a communal kitchen, which residents reserve by the hour for cooking classes or meals with neighbors. Those who use it share the running costs.", "An empty storefront in an apartment complex is now a shared kitchen. Residents rent it hourly to teach cooking or eat with neighbors, and users split the costs."]','[{"phrase": "빈 상가 → a vacant storefront / an empty shop unit", "why": "empty store building은 어색해요. 단지 안 상가 한 칸은 storefront, shop unit이에요."}, {"phrase": "시간 단위로 예약 → book it by the hour", "why": "reserve per time은 틀려요. 시간당 요금·예약은 by the hour, hourly예요."}, {"phrase": "나눠 낸다 → are split among", "why": "divide and pay로 옮기지 않아요. 비용을 여럿이 나누는 건 split이에요."}]'),
  ('생활 기사 · 손편지','20대 사이에서 손편지가 조용히 다시 인기를 얻고 있다. 손으로 쓰다 보면 속도를 늦추고 말을 더 신중하게 고르게 된다는 이들도 있다. 문구점들은 주말마다 편지 세트가 동난다고 전했다.','["손편지가 20대에게 다시 조용히 사랑받고 있다. 손으로 쓰면 천천히, 단어를 골라 쓰게 된다는 반응이 많다. 문구점에서는 주말이면 편지 세트가 품절된다고 한다.", "요즘 20대 사이에서 손편지를 쓰는 사람이 조용히 늘고 있다. 손글씨는 자연스레 속도를 늦추고 말을 아끼게 한다는 것이다. 문구점들은 주말마다 편지지 세트가 다 팔린다고 밝혔다."]','[{"phrase": "making a quiet comeback → 조용히 다시 인기를 얻다", "why": "''조용한 컴백을 하다''는 어색해요. 다시 유행한다는 뜻을 풀어요."}, {"phrase": "forces them to ~ → ~하게 된다", "why": "''강요한다''로 옮기면 부정적으로 들려요. 자연스럽게 그렇게 된다는 뜻이에요."}, {"phrase": "selling out → 동나다 / 품절되다", "why": "''매진''은 공연 표에 주로 써요. 물건이 다 팔리는 건 ''동나다'', ''품절''이에요."}]'),
  ('대역 기사 · 사회 (예시 원문)','Instead of cutting bus routes, a provincial city has introduced on-demand minibuses. Residents call one through an app, and it picks them up at the nearest stop. Ridership has grown, but some older residents who are less comfortable with smartphones say getting around has become harder.','["A regional city has replaced some of its bus routes with app-based minibuses that pick passengers up at the nearest stop on request. More people are riding, yet older residents unused to smartphones complain that travel has become less convenient.", "Rather than simply trimming routes, one provincial city now runs on-demand minibuses that residents summon by app. While ridership is up, there are complaints from elderly residents who struggle with smartphones."]','[{"phrase": "호출형 → on-demand / app-based", "why": "call-type bus는 영어에 없어요. 부르면 오는 서비스는 on-demand예요."}, {"phrase": "이용객은 늘었다 → Ridership has grown", "why": "users increased도 되지만 대중교통 기사에서는 ridership을 써요."}, {"phrase": "~는 목소리도 나온다 → some ~ say / there are complaints", "why": "voices are coming out은 직역이에요. 기사에서는 누가 무엇을 말하는지로 옮겨요."}]'),
  ('대역 기사 · 일과 노동 (예시 원문)','한 중견 디자인 회사가 임금을 깎지 않고 주 4일제로 바꾸면서, 대신 직원들에게 꼭 필요하지 않은 회의를 줄이라고 요청했다. 시행 6개월째, 회사는 업무 성과가 그대로 유지되고 병가 일수는 3분의 1 줄었다고 밝혔다. 다만 회의적인 쪽에서는 교대 근무가 정해진 업종에서도 같은 결과가 나올지는 알 수 없다고 지적한다.','["임금 삭감 없이 주 4일제를 도입한 한 중견 디자인 회사는 그 대신 불필요한 회의를 없애 달라고 직원들에게 요청했다. 6개월이 지난 지금 성과는 그대로이고 병가는 3분의 1 줄었다는 것이 회사 설명이다. 그러나 교대 근무 업종에는 그대로 적용되기 어렵다는 지적도 있다.", "한 디자인 회사가 월급은 그대로 두고 주 4일 근무를 시작했다. 대신 효과가 적은 회의를 줄였다. 반년이 지나 성과는 유지됐고 병가는 3분의 1 감소했지만, 교대제 업종에도 통할지는 미지수라는 시각이 있다."]','[{"phrase": "without cutting pay → 임금을 깎지 않고", "why": "''급여를 자르지 않고''는 직역이에요. ''임금 삭감 없이''가 기사체예요."}, {"phrase": "fallen by a third → 3분의 1 줄었다", "why": "by는 줄어든 폭이에요. ''3분의 1로 줄었다''(3분의 2 감소)와 다르고, third는 ''세 번째''가 아니에요."}, {"phrase": "Skeptics note that → 회의적인 쪽에서는 ~고 지적한다", "why": "skeptics는 회의론자, critics는 비판하는 쪽이에요. 법정 같은 다른 뜻으로 읽지 않아요."}]')
) as m(title,best,alternatives,notes) on m.title = s.title;
insert into public.weekly_reports (author, week_of, body) values
  ((select email from public.members where display_name='희주'),'2026-10-19','지난 2주는 번역 연습을 쉬어 갔어요. 천천히 다시 시작해도 괜찮아요.
자주 틀린 것 3가지를 다시 짚어 볼게요.
1. 원문 둘째 문장 빠뜨리기 → 짧은 카피라도 두 문장을 끝까지 옮겨요. 기한·혜택 정보는 보통 둘째 문장에 있어요.
2. date → plans. 친구와의 약속은 plans예요.
3. use it → try them on. 옷·신발을 입어 보는 건 try on이에요.
좋아진 점: 9월 28일 이후로 오답 노트에 새로 쌓인 표현이 없어요.
이번 주 번역 연습에 나를 위한 문장 1개를 넣었어요(꽃집 엽서, 두 문장 끝까지 옮기기).
교차번역 3회차 원문 6개도 올라왔어요. 쉬움 한 문장부터 골라 보세요.'),
  ((select email from public.members where display_name='혜림'),'2026-10-19','지난 한 주 번역 연습 5문장을 내고, 🔁 다시 도전을 6번, 피드백을 3번 요청했어요.
자주 틀린 것 3가지예요.
1. Is it still what we meet → Are we still on for ~? 잡아 둔 약속이 그대로인지 물을 때 쓰는 정해진 말이에요.
2. would be started → are starting. 이미 정해진 가까운 일정은 현재진행형으로 말해요.
3. 5번째 → 5분의 1. a fifth, a third는 분수예요. by a fifth는 ''5분의 1만큼 줄었다''예요.
좋아진 점: 지난번에 두 번 나온 until/by 실수가 10월 5일 이후로 다시 나오지 않았어요.
이번 주 번역 연습에 나를 위한 문장 1개를 넣었어요(실적 보고 슬라이드, 분수 표현).
교차번역 3회차 실전 기사에도 a third와 skeptics가 나와요. 함께 연습해 보세요.')
on conflict (author, week_of) do nothing;
insert into public.copy_briefs (id, week, title, product, target, tone, rules, sort) values
  ('cb-20261019-1','2026-10-19','Sorrelnook · 저당 그래놀라','설탕 대신 대추로 단맛을 낸 그래놀라. 한 봉 350g, 1회분 당류 3g. 9달러.','아침을 단 시리얼로 때우던 30대 직장인','담백하게. 숫자 하나(3g)로 말하기.','이메일 제목 1줄, 45자 이내. healthy, guilt-free는 쓰지 않아요.',1),
  ('cb-20261019-2','2026-10-19','Larchhollow · 산속 캐빈 숙소','와이파이 없는 숲속 캐빈 6채. 장작 난로와 별 보기 데크가 있어요. 1박 140달러, 도시에서 차로 2시간.','주말에도 업무 메시지에서 못 벗어나는 도시 직장인','고급스럽고 조용하게. 없는 것(와이파이)을 장점으로.','지하철 옥외광고 헤드라인 6단어 이하 + 작은 글씨 1줄. escape, paradise는 쓰지 않아요.',2),
  ('cb-20261019-3','2026-10-19','Haulwren · 대형 가구 수거 앱','사진 한 장 올리면 다음 날 집 앞에서 소파·침대를 수거해 가요. 쓸 만한 가구는 기부로 돌려요. 1점 25달러부터.','이사를 앞두고 버릴 가구가 막막한 1인 가구','위트 있게. 가구가 떠나는 장면으로.','앱스토어 부제목 30자 이내. easy, hassle-free는 쓰지 않아요.',3)
on conflict (id) do nothing;
insert into public.terms (id, word, pair, meaning, examples, register, domain, lang, added_by) values
  ('t-try-on','try on','(옷·신발을) 입어 보다, 신어 보다','사기 전에 맞는지 입어 보는 것. wear는 ''입고 있는 상태''라서 바꿔 쓰지 않아요.','[{"s":"I tried that jacket on at the store, but it was bigger than I expected.","t":"그 재킷 매장에서 입어 봤는데 생각보다 컸어."},{"s":"Can I try these shoes on in a size 7?","t":"이 신발 7 사이즈로 신어 봐도 될까요?"},{"s":"The fitting rooms are at the back if you''d like to try anything on.","t":"입어 보실 옷이 있으면 탈의실은 안쪽에 있어요."},{"s":"I never buy jeans without trying them on first.","t":"청바지는 꼭 먼저 입어 보고 사."}]'::jsonb,'구어','일반','en',null),
  ('t-push-back','push back (a meeting)','(회의·일정을) 미루다','일정을 뒤로 옮기는 것. delay는 일이 지연됐다는 느낌이라 부탁할 때는 push back, move를 써요.','[{"s":"Sorry, could we push tomorrow''s meeting back to the afternoon?","t":"죄송한데 내일 회의를 오후로 미룰 수 있을까요?"},{"s":"The launch has been pushed back to November.","t":"출시가 11월로 미뤄졌어요."},{"s":"Can we push our call back by 30 minutes?","t":"통화를 30분만 늦출 수 있을까요?"},{"s":"If we push the deadline back again, the client won''t be happy.","t":"마감을 또 미루면 고객이 좋아하지 않을 거예요."}]'::jsonb,'구어','비즈니스·IR','en',null),
  ('t-unattended','unattended','주인 없이 놓인, 방치된','곁에 사람이 없는 물건이나 아이를 말해요. ''주의받지 않은''으로 직역하지 않아요.','[{"s":"Please keep your belongings with you at all times. Unattended bags may be removed.","t":"소지품은 항상 직접 챙겨 주시기 바랍니다. 주인 없이 놓인 가방은 수거될 수 있습니다."},{"s":"Do not leave your luggage unattended.","t":"짐을 두고 자리를 비우지 마세요."},{"s":"Children must not be left unattended in the pool area.","t":"수영장에서는 아이를 혼자 두지 마세요."},{"s":"Never leave a candle burning unattended.","t":"촛불을 켜 둔 채 자리를 비우지 마세요."}]'::jsonb,'문어','공문·행정','en',null),
  ('t-comeback','make a comeback','다시 인기를 얻다, 다시 유행하다','한동안 잊혔던 것이 다시 쓰이거나 유행하는 것. ''컴백을 하다''로 직역하지 않아요.','[{"s":"Handwritten letters are making a quiet comeback among people in their twenties.","t":"20대 사이에서 손편지가 조용히 다시 인기를 얻고 있다."},{"s":"Film cameras have made a big comeback.","t":"필름 카메라가 다시 크게 유행하고 있어요."},{"s":"Vinyl records are making a comeback in small record shops.","t":"작은 음반 가게에서 LP가 다시 인기예요."},{"s":"Wide-leg jeans made a comeback this fall.","t":"올가을 와이드 청바지가 다시 유행했어요."}]'::jsonb,'구어','일반','en',null),
  ('t-sugeo','수거될 수 있습니다','치워질 수 있어요 → 수거될 수 있습니다 → 수거 조치될 수 있습니다','may be removed / collected (안내문에서 방치된 물건을 치운다고 알릴 때)','[{"s":"주인 없이 놓인 가방은 수거될 수 있습니다.","t":"Unattended bags may be removed."},{"s":"복도에 둔 개인 물품은 예고 없이 수거될 수 있습니다.","t":"Personal items left in the hallway may be removed without notice."},{"s":"분리배출 기준에 맞지 않는 쓰레기는 수거되지 않습니다.","t":"Waste that isn''t sorted properly will not be collected."},{"s":"장기간 방치된 자전거는 수거될 수 있습니다.","t":"Bicycles left for a long time may be removed."}]'::jsonb,'문어','공문·행정','ko',null),
  ('t-dongnada','동나다','다 팔리다 → 동나다 → 품절되다','sell out (물건이 다 팔려 없어지는 것, 구어·기사 모두)','[{"s":"문구점들은 주말마다 편지 세트가 동난다고 전했다.","t":"Stationery shops report that letter sets are selling out on weekends."},{"s":"오후 2시면 소금빵이 다 동나요.","t":"The salt bread is usually sold out by 2 p.m."},{"s":"태풍 소식에 생수가 금세 동났다.","t":"Bottled water sold out quickly after the typhoon warning."},{"s":"인기 사이즈는 벌써 동났어요.","t":"The popular sizes have already sold out."}]'::jsonb,'구어','일반','ko',null)
on conflict (id) do nothing;
commit;
